Evt_Entry* evt_search( UInt8 event )
{
    UInt8     index = 0   ;
    Evt_Entry *ret  = NULL;
 
  	do
  	{
    	if( evt_table[index].evt == event )
        { 
            ret = (Evt_Entry*)&evt_table[index] ;
            
            break ;
        }
 	}
  	while (++index < EVT_TABLE_SIZE ) ; 

    return ret ;
}

